#include <string>
#include <algorithm>
using namespace std;

class Solution {
public:
    int findTheLongestBalancedSubstring(string s) {
        int max_len = 0;
        int n = s.size();
        int i = 0;
        while (i < n) {
            int zeros = 0;
            while (i < n && s[i] == '0') {
                zeros++;
                i++;
            }
            int ones = 0;
            while (i < n && s[i] == '1') {
                ones++;
                i++;
            }
            max_len = max(max_len, 2 * min(zeros, ones));
        }
        return max_len;
    }
};

class Solution {
    public int findTheLongestBalancedSubstring(String s) {
        int maxLen = 0;
        int n = s.length();
        int i = 0;
        while (i < n) {
            int zeros = 0;
            while (i < n && s.charAt(i) == '0') {
                zeros++;
                i++;
            }
            int ones = 0;
            while (i < n && s.charAt(i) == '1') {
                ones++;
                i++;
            }
            maxLen = Math.max(maxLen, 2 * Math.min(zeros, ones));
        }
        return maxLen;
    }
}

